//#region src/lib/admin/product-photo-mode.ts
var VALID_MODES = [
	"normal",
	"webp",
	"script",
	"script-webp"
];
function isProductPhotoMode(value) {
	return !!value && VALID_MODES.includes(value);
}
/** Modes where the server runs the full enhance-product-photo pipeline
* (crop to the alpha bounding box, tone correction, watermark) instead of
* just storing the client-compressed file as-is. */
function usesScriptProcessing(mode) {
	return mode === "script" || mode === "script-webp";
}
/** Modes whose final stored file should be WebP. */
function usesWebpOutput(mode) {
	return mode === "webp" || mode === "script-webp";
}
//#endregion
//#region src/lib/admin/product-image-attach.ts
function mediaUrlForCurrentWriteTarget(supabase, bucket, path) {
	if (process.env.MEDIA_STORAGE_WRITE_TARGET === "r2") {
		const baseUrl = process.env.NEXT_PUBLIC_MEDIA_BASE_URL;
		if (!baseUrl) throw new Error("Переменная окружения NEXT_PUBLIC_MEDIA_BASE_URL не задана для Cloudflare R2.");
		return buildR2PublicUrl(baseUrl, bucket, path);
	}
	return supabase.storage.from(bucket).getPublicUrl(path).data.publicUrl;
}
/**
* Загрузка варианта, безопасная к повтору.
*
* Имя файла варианта — хеш его содержимого, поэтому объект по такому пути
* либо отсутствует, либо байт-в-байт совпадает с тем, что мы собираемся
* записать. Значит конфликт имени — это «уже загружено» (повторный
* finalize, повторный проход backfill), а не расхождение: перезаписывать
* нечего, и `upsert` остаётся выключенным, как требует план.
*/
async function uploadImageVariant(supabase, variant) {
	await uploadPublicMediaObject(supabase, {
		bucket: "product-images",
		path: variant.path,
		body: variant.body,
		contentType: VARIANT_UPLOAD_OPTIONS.contentType,
		cacheControl: VARIANT_UPLOAD_OPTIONS.cacheControl,
		allowExisting: true
	});
}
async function applyPhotoMode(file, photoMode) {
	if (!usesScriptProcessing(photoMode)) return file;
	const enhanced = await enhanceProductPhotoBuffer(Buffer.from(await file.arrayBuffer()));
	const toWebp = usesWebpOutput(photoMode);
	const finalBuffer = toWebp ? await convertBufferToWebp(enhanced) : enhanced;
	const extension = toWebp ? "webp" : "png";
	const newName = file.name.replace(/\.[^./]+$/, "") + "." + extension;
	return new File([new Uint8Array(finalBuffer)], newName, { type: toWebp ? "image/webp" : "image/png" });
}
/**
* Обрабатывает одну фотографию из промежуточного хранилища и привязывает её к товару.
* Повтор безопасен: идентификатор строки стабилен, поэтому master и варианты ложатся по тем же
* путям, а уже созданная строка product_images не дублируется. Бросает ошибку при любом сбое.
*/
async function attachStagedImageRow(options) {
	const { supabase, row, productId, productSlug, photoMode, order } = options;
	const downloaded = await supabase.storage.from(PRODUCT_IMAGE_STAGING_BUCKET).download(row.object_path);
	if (downloaded.error) throw downloaded.error;
	const bytes = new Uint8Array(await downloaded.data.arrayBuffer());
	const extension = CANONICAL_UPLOAD_EXTENSION[row.content_type];
	if (!extension) throw new Error(`Недопустимый тип файла: ${row.content_type}.`);
	const staging = new File([bytes], `staged.${extension}`, { type: row.content_type });
	await validateRasterImage(staging);
	const validated = await validateRasterImage(await applyPhotoMode(staging, photoMode));
	const masterUrl = await uploadPublicMediaObject(supabase, {
		bucket: "product-images",
		path: `${productSlug}/${row.id}/master.${validated.extension}`,
		body: validated.bytes,
		contentType: validated.contentType,
		cacheControl: "31536000",
		allowExisting: true
	});
	const { thumbnail, gallery } = await generateProductImageVariants(Buffer.from(validated.bytes), {
		productSlug,
		imageId: row.id
	});
	for (const variant of [thumbnail, gallery]) await uploadImageVariant(supabase, variant);
	const publicUrl = (path) => mediaUrlForCurrentWriteTarget(supabase, "product-images", path);
	const { data: already } = await supabase.from("product_images").select("id").eq("url", masterUrl).maybeSingle();
	let inserted = false;
	if (!already) {
		const { error: insertError } = await supabase.from("product_images").insert({
			product_id: productId,
			url: masterUrl,
			thumbnail_url: publicUrl(thumbnail.path),
			gallery_url: publicUrl(gallery.path),
			order
		});
		if (insertError) throw insertError;
		inserted = true;
	}
	await supabase.rpc("finalize_product_image_staging", { p_id: row.id });
	await supabase.storage.from(PRODUCT_IMAGE_STAGING_BUCKET).remove([row.object_path]);
	return { inserted };
}
//#endregion
//#region src/lib/photo-queue/runner.ts
async function runPhotoQueue(ports, options) {
	const startedAt = options.now();
	const reserve = options.expectedJobMs ?? 0;
	let processed = 0;
	let failed = 0;
	for (;;) {
		if (options.now() - startedAt + reserve >= options.deadlineMs) return {
			processed,
			failed,
			stopped: "deadline"
		};
		const job = await ports.claim();
		if (!job) return {
			processed,
			failed,
			stopped: "empty"
		};
		const info = job.queued_product_id ? await ports.productInfo(job.queued_product_id) : null;
		if (!info) {
			failed += 1;
			await ports.fail(job.id, false);
			continue;
		}
		if (options.maxImages !== void 0 && info.imageCount >= options.maxImages) {
			failed += 1;
			await ports.fail(job.id, false);
			continue;
		}
		try {
			await ports.attach(job, info);
			processed += 1;
		} catch (error) {
			failed += 1;
			console.error(`[photo-queue] photo ${job.id} failed (attempt ${job.attempts}): ${error instanceof Error ? error.name : typeof error}`);
			await ports.fail(job.id, true);
		}
	}
}
/**
* Removes abandoned staged files. The files go first and the records only afterwards: a record
* freed before its file is gone would leave a file nobody knows about.
*/
async function cleanupAbandonedStaging(ports) {
	const rows = await ports.list();
	if (rows.length === 0) return 0;
	await ports.removeFiles(rows.map((row) => row.out_object_path));
	await ports.release(rows.map((row) => row.out_id));
	return rows.length;
}
//#endregion
//#region src/lib/photo-queue/enqueue.ts
var REPOSITORY = /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/;
var WORKFLOW_FILE = /^[A-Za-z0-9_.-]+\.ya?ml$/;
var GIT_REF = /^[A-Za-z0-9_./-]{1,100}$/;
var GITHUB_ENVIRONMENT = /^(staging|production)$/;
/** Starts a GitHub workflow. Returns false (never throws): a missed wake-up must not break saving. */
async function dispatchWorkflow(env, names, label, fetchImpl) {
	const token = env.GITHUB_DISPATCH_TOKEN?.trim();
	const repository = env.GITHUB_REPOSITORY?.trim();
	const workflow = env[names.file]?.trim();
	const ref = env[names.ref]?.trim() || "main";
	if (!token || !repository || !workflow) return false;
	if (!REPOSITORY.test(repository) || repository.includes("..") || !WORKFLOW_FILE.test(workflow) || !GIT_REF.test(ref) || ref.includes("..")) {
		console.error(`[${label}] invalid worker configuration`);
		return false;
	}
	const environment = env.WORKFLOW_ENVIRONMENT?.trim();
	if (environment && !GITHUB_ENVIRONMENT.test(environment)) {
		console.error(`[${label}] invalid worker configuration`);
		return false;
	}
	try {
		const response = await fetchImpl(`https://api.github.com/repos/${repository}/actions/workflows/${workflow}/dispatches`, {
			method: "POST",
			headers: {
				authorization: `Bearer ${token}`,
				accept: "application/vnd.github+json",
				"x-github-api-version": "2022-11-28",
				"user-agent": "ayprom-admin",
				"content-type": "application/json"
			},
			body: JSON.stringify(environment ? {
				ref,
				inputs: { environment }
			} : { ref }),
			signal: AbortSignal.timeout(5e3)
		});
		if (!response.ok) console.error(`[${label}] worker start refused: ${response.status}`);
		return response.ok;
	} catch (error) {
		console.error(`[${label}] worker start failed: ${error instanceof Error ? error.name : typeof error}`);
		return false;
	}
}
/** Cloudflare admin: edits reach the public site through a published snapshot, built by this workflow. */
function isPublicationEnabled(env = process.env) {
	return Boolean(env.PUBLICATION_WORKFLOW_FILE?.trim());
}
/** Starts the publication workflow. */
function requestPublicationWorker(env = process.env, fetchImpl = fetch) {
	return dispatchWorkflow(env, {
		file: "PUBLICATION_WORKFLOW_FILE",
		ref: "PUBLICATION_WORKFLOW_REF"
	}, "publication", fetchImpl);
}
//#endregion
//#region src/lib/photo-queue/main.ts
var LEASE_SECONDS = 300;
var BUDGET_MS = 72e4;
var EXPECTED_JOB_MS = 6e4;
var WATCH_POLL_MS = 1500;
var CLEANUP_EVERY_MS = 6e5;
var supabase = createAdminClient();
var ports = {
	async claim() {
		const { data, error } = await supabase.rpc("claim_queued_product_image_staging", { p_lease_seconds: LEASE_SECONDS });
		if (error) throw error;
		return (data ?? [])[0] ?? null;
	},
	async productInfo(productId) {
		const { data } = await supabase.from("products").select("slug").eq("id", productId).maybeSingle();
		if (!data) return null;
		const { count } = await supabase.from("product_images").select("id", {
			count: "exact",
			head: true
		}).eq("product_id", productId);
		return {
			slug: data.slug,
			imageCount: count ?? 0
		};
	},
	async attach(job, info) {
		const mode = job.queued_photo_mode && isProductPhotoMode(job.queued_photo_mode) ? job.queued_photo_mode : "normal";
		return attachStagedImageRow({
			supabase,
			row: {
				id: job.id,
				object_path: job.object_path,
				content_type: job.content_type
			},
			productId: job.queued_product_id,
			productSlug: info.slug,
			photoMode: mode,
			order: info.imageCount
		});
	},
	async fail(id, retry) {
		await supabase.rpc("fail_queued_product_image_staging", {
			p_id: id,
			p_retry: retry
		});
	}
};
async function cleanup() {
	return cleanupAbandonedStaging({
		async list() {
			const { data, error } = await supabase.rpc("list_abandoned_product_image_staging", { p_limit: 100 });
			if (error) throw error;
			return data ?? [];
		},
		async removeFiles(paths) {
			const { error } = await supabase.storage.from(PRODUCT_IMAGE_STAGING_BUCKET).remove(paths);
			if (error) throw error;
		},
		async release(ids) {
			const { error } = await supabase.rpc("release_product_image_staging", { p_ids: ids });
			if (error) throw error;
		}
	});
}
async function main() {
	const watch = process.argv.includes("--watch");
	let lastCleanup = 0;
	do {
		const result = await runPhotoQueue(ports, {
			now: Date.now,
			deadlineMs: BUDGET_MS,
			expectedJobMs: EXPECTED_JOB_MS,
			maxImages: 10
		});
		if (result.processed || result.failed) console.log(`[photo-queue] processed=${result.processed} failed=${result.failed} stopped=${result.stopped}`);
		if (result.processed > 0 && isPublicationEnabled()) await requestPublicationWorker();
		if (Date.now() - lastCleanup >= CLEANUP_EVERY_MS || !watch) {
			lastCleanup = Date.now();
			try {
				const removed = await cleanup();
				if (removed) console.log(`[photo-queue] removed ${removed} abandoned staged files`);
			} catch (error) {
				console.error(`[photo-queue] cleanup failed: ${error instanceof Error ? error.name : typeof error}`);
			}
		}
		if (watch) await new Promise((resolve) => setTimeout(resolve, WATCH_POLL_MS));
	} while (watch);
}
main().catch((error) => {
	console.error(`[photo-queue] stopped: ${error instanceof Error ? error.name : typeof error}`);
	process.exit(1);
});
//#endregion
export {};
